<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Accessor\UserBlockedUntilAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserBlockedUntilAccessor trait.
 *
 * Covers null default, string/VO assignment via withBlockedUntil,
 * getBlockedUntil/blockedUntil accessors, and isBlockedUntilChanged with/without original.
 */
class UserBlockedUntilAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withBlockedUntil creates a new instance with the BlockedUntil set
     * from a string value, and getBlockedUntil returns the primitive string.
     */
    public function testWithBlockedUntilFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserBlockedUntilAccessorUnitTest();

        // Act
        $result = $holder->withBlockedUntil((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getBlockedUntil());
    }
    /**
     * Asserts that withblockedUntil has access to the value object
     * from a string value, and getBlockedUntil returns the primitive string.
     */
    public function testWithBlockedUntilFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserBlockedUntilAccessorUnitTest();

        // Act
        $result = $holder->withBlockedUntil((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->blockedUntil()->value());
    }
    public function testChangedBlockedUntil(): void
    {
        // Arrange
        $holder = new ImplWithUserBlockedUntilAccessorUnitTest();
        $original = $holder->withBlockedUntil( (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withBlockedUntil( (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withBlockedUntil((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isBlockedUntilChanged();
        $withSame = $original->isBlockedUntilChanged( $same );
        $withDiferent = $original->isBlockedUntilChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserBlockedUntilAccessorUnitTest
{
  use UserBlockedUntilAccessor;
}
